// TH14 v1.00b st06bs.ecl.txt::Boss2 (161-216) + Boss2_at (218-323) + BossCup (1918-1940).
// Card frame0 = full Boss2 entry; source t0 (timerReset, line170) starts after the120-frame opening.
// Source 3000-frame slot0 timeout is the emission stop; the extra window is tail only.
const TIME_LIMIT: int = 3424;
const SOURCE_LIMIT: int = 3000;
const OPENING_BUFFER: int = 120;

// Source first stream etEx type4 ACCEL: a=90, r=1/15, s=pi/2 literal -> constant downward velocity gain.
// Birth stage omitted by policy; the ANIM 4*speed retreat is folded into each spawn point.
xformdef DOWN_ACCEL {
    @90 set_gravity(0fx, 0.0666667fx);
    set_gravity(0fx, 0fx);
}
// Source cup-break wave (250-277): EX ANIM, explicit WAIT30, ACCEL a=90 r=0.0444444 s=-999999 (own angle).
xformdef ALONG_ACCEL {
    wait(30);
    @90 set_accel(0.0444444fx);
    set_accel(0fx);
}
// Source third stream (278-322): ACCEL a=90 r=0.0444444 s=999.0 is a literal angle, not the keep-angle
// sentinel (TH16/TH18 ACCEL keeps current angle only at q<=-999990). 999rad wraps to ~-276 BAM.
xformdef SKEW_ACCEL {
    @90 set_gravity(0.044429fx, -0.001176fx);
    set_gravity(0fx, 0fx);
}

// Source BossCup (1918-1940): wait until internal LIFE<20000, then release I1=0.  Cup visuals and
// flagExtDmg omitted.  No DPS in this shell, so HP stays at the entry lifeSet(32800) value.
async sub cup() {
    var until: int = self_int(1);
    while $self_hp >= 20000 {
        if $frame >= until { return; }
        wait(1);
    }
    set_self_int(0, 0);
}

// Source Boss2_at (218-323). Emitter configs become per-bullet fire (independent random sample per
// bullet in source order); I1 lives in shared enemy int slot0 because Boss2 body and Cup both write it.
async sub boss2_at() {
    var until: int = self_int(1);
    // Source 231-232 %E=%RANDRAD, %F=96; E/F are never read in this closure. Keep the draw point.
    var unused_rad: int = rand(65536);
    var rank: int = global(GVAR_RANK);
    // Source 236 diffI($D, 1,1,2,3): bullets per cycle.
    var d: int = 1;
    if rank == 2 { d = 2; }
    if rank == 3 { d = 3; }
    var c: int = 20000;
    loop {
        if $frame >= until { return; }
        for i in 0..d {
            // Source 239-241 per bullet: RANDF2 angle, RANDF speed, RANDF2 x offset, RANDF y offset.
            var ua: fx = ((rand(65536)-32768) as fx)/32768;
            var a: angle = (-16384+(16384fx*ua) as int) as angle;
            var us: fx = ((rand(65536)-32768) as fx)/65536+0.5fx;
            var speed: fx = 1.5fx+us*3fx;
            if rank == 3 { speed = 1.5fx+us*1.5fx; }
            var ux: fx = ((rand(65536)-32768) as fx)/32768;
            var ox: fx = ux*96fx;
            var uy: fx = ((rand(65536)-32768) as fx)/65536+0.5fx;
            var oy: fx = uy*32fx;
            // ANIM a=1 enters with position -= 4*initial velocity.
            var sx: fx = $self_x+ox-4fx*speed*cos(a);
            var sy: fx = $self_y+oy-4fx*speed*sin(a);
            _ = fire(TH14_FIREBALL_BLUE, 0, sx, sy, speed, a, DOWN_ACCEL, none);
        }
        // Source 245-249: wait($I1); I1==0 exits to the next block, else the C=20000 cycle guard.
        wait(self_int(0));
        if self_int(0) == 0 { break; }
        if c == 0 { break; }
        c = c-1;
    }

    // Source 250-277: one ring wave. Difficulty pushes count then layers, and etCount([-1],[-2]) reads
    // top=layers-value as path count and [-2]=count-value as layer count.
    var n: int = 48;
    if rank == 0 { n = 25; }
    var m: int = 1;
    if rank == 2 { m = 2; }
    if rank == 3 { m = 3; }
    var aim: angle = aim_player();
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 3);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_angle(0, aim, 0deg);
    for q in 0..m {
        // Speed layers v(q)=1.0+(0.5-1.0)*q/(m-1); ANIM retreat4*v per layer via sh_dist.
        var v: fx = 1fx;
        if m > 1 { v = 1fx-0.5fx*(q as fx)/((m-1) as fx); }
        sh_speed(0, v, 0fx);
        sh_dist(0, -4fx*v);
        sh_fire(0);
    }

    // Source 278-322: second stream, H=1/1/1/2 bullets per cycle and idle wait4/1/1/1.
    var unused_rad2: int = rand(65536);
    var h: int = 1;
    if rank == 3 { h = 2; }
    var idle: int = 1;
    if rank == 0 { idle = 4; }
    var g: int = 20000;
    loop {
        for j in 0..h {
            if $frame >= until { return; }
            // Source 295-306: RANDF2 angle, RANDF speed, RANDRAD offset angle, RANDF offset radius.
            var ub: fx = ((rand(65536)-32768) as fx)/32768;
            var ab: angle = (-16384+(5461fx*ub) as int) as angle;
            var us2: fx = ((rand(65536)-32768) as fx)/65536+0.5fx;
            var speed2: fx = 1.5fx+us2*1fx;
            if rank == 3 { speed2 = 1.5fx+us2*1.5fx; }
            var ao: angle = ((rand(65536)-32768) as angle);
            var ur: fx = ((rand(65536)-32768) as fx)/65536+0.5fx;
            var ox2: fx = ur*32fx*cos(ao);
            var oy2: fx = ur*32fx*sin(ao);
            var sx2: fx = $self_x+ox2-4fx*speed2*cos(ab);
            var sy2: fx = $self_y+oy2-4fx*speed2*sin(ab);
            _ = fire(TH14_PELLET2, 6, sx2, sy2, speed2, ab, SKEW_ACCEL, none);
        }
        wait(idle);
        if g == 0 { return; }
        g = g-1;
    }
}

// Source Boss2 entry (161-216). Drops, anm/playSound/stars/callSTD, boundary killAllAsync/enmKillAll,
// entry etCancel/etClear(640) and TIMEOUT branch are omitted per policy; timerReset/setInterrupt/lifeMarker
// are carried by the phase shell. movePosTime(60,4,0,128) keeps its 60-frame re-centering slot.
async sub pattern() {
    wait(OPENING_BUFFER);
    var t0: int = $frame;
    set_self_int(1, t0+SOURCE_LIMIT);
    set_self_int(0, 0);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60); // source 194
    wait(80); // source 199, EffChargePoint2 omitted as visual
    // Source 200 moveLimit(0,128,280,96): the boss has no movement in this attack, so the box never binds.
    spawn cup(); // source 202, t=140
    wait(60); // source 203
    set_self_int(0, 10); // source 204
    spawn boss2_at(); // source 205, source t=200
    // Source 206-207 %F0=0.040143 is never read in this closure; diffI($A,3,1,1,1) sets the I1 floor.
    var a: int = 3;
    if global(GVAR_RANK) != 0 { a = 1; }
    // Source 209-214: wait60 then decrement I1 while I1>A.
    loop {
        if $frame >= t0+SOURCE_LIMIT { return; }
        wait(60);
        if self_int(0) > a { set_self_int(0, self_int(0)-1); }
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx); // source Boss context setHitbox(48,48)
    set_hurtbox(24fx); // source Boss context setHurtbox(48,48); damage disabled here
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 32800, 0, 0, 0, boss_main); // lifeSet(32800), Boss movePos(0,128)
    loop { wait(600); }
}
